result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "lisp.py", "content": """"A minimal Lisp: s-expression reader, lexical-scope evaluator, REPL."""


class LispError(Exception):
    """Raised for all runtime/reader errors; message names the culprit."""


# ---------------------------------------------------------------- symbols

class Symbol(str):
    pass


_symbols = {}


def intern(name):
    return _symbols.setdefault(name, Symbol(name))


_quote = intern("quote")
_define = intern("define")
_lambda = intern("lambda")
_if = intern("if")
_begin = intern("begin")


# ---------------------------------------------------------------- reader

def tokenize(src):
    tokens, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c.isspace():
            i += 1
        elif c == ";":
            while i < n and src[i] != "\n":
                i += 1
        elif c in "()'":
            tokens.append(c)
            i += 1
        else:
            j = i
            while j < n and not src[j].isspace() and src[j] not in "()'":
                j += 1
            tokens.append(src[i:j])
            i = j
    return tokens


def _read(tokens, pos):
    tok = tokens[pos]
    pos += 1
    if tok == "(":
        items = []
        while True:
            if pos >= len(tokens):
                raise LispError("unexpected end of input: missing ')'")
            if tokens[pos] == ")":
                return items, pos + 1
            item, pos = _read(tokens, pos)
            items.append(item)
    if tok == ")":
        raise LispError("unexpected ')' with no matching '('")
    if tok == "'":
        if pos >= len(tokens):
            raise LispError("unexpected end of input after quote")
        item, pos = _read(tokens, pos)
        return [_quote, item], pos
    try:
        return int(tok), pos
    except ValueError:
        return intern(tok), pos


def parse(src):
    """Parse a program into a list of top-level expressions."""
    tokens = tokenize(src)
    exprs, pos = [], 0
    while pos < len(tokens):
        expr, pos = _read(tokens, pos)
        exprs.append(expr)
    return exprs


# ---------------------------------------------------------------- values

class Lambda:
    __slots__ = ("params", "body", "env")

    def __init__(self, params, body, env):
        self.params = params
        self.body = body  # list of expressions (implicit begin)
        self.env = env


class Pair:
    """Cons cell for builtins cons/car/cdr."""

    __slots__ = ("car", "cdr")

    def __init__(self, car, cdr):
        self.car = car
        self.cdr = cdr


def to_pylist(x):
    out = []
    while x is not None:
        if not isinstance(x, Pair):
            raise LispError("improper list cannot be converted")
        out.append(x.car)
        x = x.cdr
    return out


def from_pylist(items):
    result = None
    for item in reversed(items):
        result = Pair(item, result)
    return result


# ---------------------------------------------------------------- eval

def evaluate(expr, env):
    while True:
        if isinstance(expr, Symbol):
            try:
                return env[expr]
            except KeyError:
                raise LispError(f"unbound symbol: {expr}")
        if not isinstance(expr, list):
            return expr  # self-evaluating (integers)
        if not expr:
            raise LispError("cannot evaluate empty list ()")
        head = expr[0]
        if head is _quote:
            return expr[1]
        if head is _define:
            target = expr[1]
            if isinstance(target, list):  # sugar: (define (f a) body...)
                name, params = target[0], target[1]
                env[name] = Lambda(params, expr[2:], env)
            else:
                env[target] = evaluate(expr[2], env)
            return None
        if head is _lambda:
            return Lambda(expr[1], expr[2:], env)
        if head is _if:
            _, cond, then, els = expr
            expr = then if evaluate(cond, env) is not False else els
            continue
        if head is _begin:
            if len(expr) == 1:
                return None
            for sub in expr[1:-1]:
                evaluate(sub, env)
            expr = expr[-1]  # tail position
            continue
        # application
        fn = evaluate(head, env)
        args = [evaluate(a, env) for a in expr[1:]]
        if isinstance(fn, Lambda):
            if len(args) != len(fn.params):
                raise LispError(
                    f"wrong arity for lambda: expected {len(fn.params)}, got {len(args)}")
            new_env = Env(dict(zip(fn.params, args)), fn.env)
            body = fn.body
            for sub in body[:-1]:
                evaluate(sub, new_env)
            expr = body[-1]  # tail call
            env = new_env
            continue
        if callable(fn):
            return fn(*args)
        raise LispError(f"not callable: {fn}")


class Env(dict):
    def __init__(self, params, outer=None):
        super().__init__(params)
        self.outer = outer

    def __contains__(self, key):
        return dict.__contains__(self, key) or (
            self.outer is not None and key in self.outer)

    def __getitem__(self, key):
        if dict.__contains__(self, key):
            return dict.__getitem__(self, key)
        if self.outer is not None:
            return self.outer[key]
        raise KeyError(key)


# ---------------------------------------------------------------- builtins

def _check_arity(name, args, n):
    if len(args) != n:
        raise LispError(f"wrong arity for builtin {name}: "
                        f"expected {n}, got {len(args)}")


def _num_check(name, args):
    for a in args:
        if not isinstance(a, int):
            raise LispError(f"builtin {name} requires integers, got {a!r}")


def builtin_add(*args):
    if not args:
        raise LispError("wrong arity for builtin +: at least 1 argument required")
    _num_check("+", args)
    total = 0
    for a in args:
        total += a
    return total


def builtin_sub(*args):
    if not args:
        raise LispError("wrong arity for builtin -: at least 1 argument required")
    _num_check("-", args)
    if len(args) == 1:
        return -args[0]
    acc = args[0]
    for a in args[1:]:
        acc -= a
    return acc


def builtin_mul(*args):
    if not args:
        raise LispError("wrong arity for builtin *: at least 1 argument required")
    _num_check("*", args)
    product = 1
    for a in args:
        product *= a
    return product


def builtin_div(a, b):
    _check_arity("/", (a, b), 2)
    _num_check("/", (a, b))
    if b == 0:
        raise LispError("/ by zero")
    if a % b == 0:
        return a // b
    return a / b


def make_global_env():
    def eq(a, b):
        return a == b and isinstance(a, type(b)) or (
            isinstance(a, bool) == isinstance(b, bool) and a == b)

    def lt(a, b):
        _check_arity("<", (a, b), 2)
        return a < b

    def gt(a, b):
        _check_arity(">", (a, b), 2)
        return a > b

    def cons(a, d):
        _check_arity("cons", (a, d), 2)
        return Pair(a, d)

    def car(p):
        _check_arity("car", (p,), 1)
        if not isinstance(p, Pair):
            raise LispError(f"car of non-pair: {p!r}")
        return p.car

    def cdr(p):
        _check_arity("cdr", (p,), 1)
        if not isinstance(p, Pair):
            raise LispError(f"cdr of non-pair: {p!r}")
        return p.cdr

    def lst(*args):
        return from_pylist(list(args))

    def null_p(x):
        return x is None

    return {
        "+": builtin_add,
        "-": builtin_sub,
        "*": builtin_mul,
        "/": builtin_div,
        "=": lambda a, b: (_check_arity("=", (a, b), 2), a == b)[1],
        "<": lt,
        ">": gt,
        "cons": cons,
        "car": car,
        "cdr": cdr,
        "list": lst,
        "null?": null_p,
    }


GLOBAL_ENV = Env(make_global_env())


# ---------------------------------------------------------------- api

def run(src):
    """Evaluate a program string; return the value of every top-level form."""
    return [evaluate(expr, Env({}, GLOBAL_ENV)) for expr in parse(src)]


def repl():
    print("mini-lisp. Ctrl-D to exit.")
    while True:
        try:
            line = input("lisp> ")
        except EOFError:
            print()
            break
        if not line.strip():
            continue
        try:
            results = run(line)
            for r in results:
                print(repr(r))
        except LispError as e:
            print(f"error: {e}")


if __name__ == "__main__":
    repl()
